265→/// Standard JSON-RPC 2.0 request envelope
266→#[derive(Debug, Clone, Serialize, Deserialize)]
267→pub struct JsonRpcRequest<T> {
268→    pub jsonrpc: String,
269→    pub id: serde_json::Value,
270→    pub method: String,
271→    pub params: T,
272→}
273→
274→impl<T> JsonRpcRequest<T> {
275→    /// Create a new JSON-RPC 2.0 request
276→    pub fn new(id: impl Into<serde_json::Value>, method: impl Into<String>, params: T) -> Self {
277→        Self {
278→            jsonrpc: "2.0".to_string(),
279→            id: id.into(),
280→            method: method.into(),
281→            params,
282→        }
283→    }
284→}
285→
286→/// Standard JSON-RPC 2.0 response envelope
287→#[derive(Debug, Clone, Serialize, Deserialize)]
288→pub struct JsonRpcResponse<T> {
289→    pub jsonrpc: String,
290→    pub id: serde_json::Value,
291→    #[serde(skip_serializing_if = "Option::is_none")]
292→    pub result: Option<T>,
293→    #[serde(skip_serializing_if = "Option::is_none")]
294→    pub error: Option<JsonRpcError>,
295→}
296→
297→impl<T> JsonRpcResponse<T> {
298→    /// Create a successful response
299→    pub fn success(id: impl Into<serde_json::Value>, result: T) -> Self {
300→        Self {
301→            jsonrpc: "2.0".to_string(),
302→            id: id.into(),
303→            result: Some(result),
304→            error: None,
305→        }
306→    }
307→
308→    /// Create an error response
309→    pub fn error(id: impl Into<serde_json::Value>, error: JsonRpcError) -> Self {
310→        Self {
311→            jsonrpc: "2.0".to_string(),
312→            id: id.into(),
313→            result: None,
314→            error: Some(error),
315→        }
316→    }
317→}
318→
319→/// JSON-RPC 2.0 error object
320→#[derive(Debug, Clone, Serialize, Deserialize)]
321→pub struct JsonRpcError {
322→    pub code: i32,
323→    pub message: String,
324→    #[serde(skip_serializing_if = "Option::is_none")]
325→    pub data: Option<serde_json::Value>,
326→}
327→
328→impl JsonRpcError {
329→    /// Create a new error
330→    pub fn new(code: i32, message: impl Into<String>) -> Self {
331→        Self {
332→            code,
333→            message: message.into(),
334→            data: None,
335→        }
336→    }
337→
338→    /// Create an error with additional data
339→    pub fn with_data(
340→        code: i32,
341→        message: impl Into<String>,
342→        data: impl Into<serde_json::Value>,
343→    ) -> Self {
344→        Self {
345→            code,
346→            message: message.into(),
347→            data: Some(data.into()),
348→        }
349→    }
350→}
351→
352→/// Standard JSON-RPC error codes
353→pub mod error_codes {
354→    pub const PARSE_ERROR: i32 = -32700;
355→    pub const INVALID_REQUEST: i32 = -32600;
356→    pub const METHOD_NOT_FOUND: i32 = -32601;
357→    pub const INVALID_PARAMS: i32 = -32602;
358→    pub const INTERNAL_ERROR: i32 = -32603;
359→}
