361→/// Method names for the system adapter protocol
362→pub mod methods {
363→    pub const SETUP: &str = "setup";
364→    pub const QUERY_METHOD: &str = "query_method";
365→    pub const TEARDOWN: &str = "teardown";
366→    pub const METRICS: &str = "metrics";
367→    pub const RPC_METHODS: &str = "rpc.methods";
368→}
