 17→//! Client implementations for system adapter JSON-RPC communication.
 18→
 19→use crate::{JsonRpcError, JsonRpcRequest, JsonRpcResponse, methods};
 20→use serde::{Serialize, de::DeserializeOwned};
 21→use std::collections::HashMap;
 22→use tokio::{
 23→    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
 24→    process::{Child, ChildStdin, ChildStdout, Command},
 25→};
 26→
 27→/// Result type for client operations
 28→pub type Result<T> = std::result::Result<T, ClientError>;
 29→
 30→/// Errors that can occur during client operations
 31→#[derive(Debug)]
 32→pub enum ClientError {
 33→    /// JSON-RPC error returned by the server
 34→    JsonRpc(JsonRpcError),
 35→    /// I/O error during communication
 36→    Io(std::io::Error),
 37→    /// JSON serialization/deserialization error
 38→    Json(serde_json::Error),
 39→    /// HTTP transport error
 40→    #[cfg(feature = "client")]
 41→    Http(reqwest::Error),
 42→    /// Invalid response format
 43→    InvalidResponse(String),
 44→    /// Transport-specific error
 45→    Transport(String),
 46→}
 47→
 48→impl std::fmt::Display for ClientError {
 49→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
 50→        match self {
 51→            Self::JsonRpc(e) => write!(f, "JSON-RPC error: {}", e.message),
 52→            Self::Io(e) => write!(f, "I/O error: {e}"),
 53→            Self::Json(e) => write!(f, "JSON error: {e}"),
 54→            #[cfg(feature = "client")]
 55→            Self::Http(e) => write!(f, "HTTP error: {e}"),
 56→            Self::InvalidResponse(msg) => write!(f, "Invalid response: {msg}"),
 57→            Self::Transport(msg) => write!(f, "Transport error: {msg}"),
 58→        }
 59→    }
 60→}
 61→
 62→impl std::error::Error for ClientError {}
 63→
 64→impl From<std::io::Error> for ClientError {
 65→    fn from(e: std::io::Error) -> Self {
 66→        Self::Io(e)
 67→    }
 68→}
 69→
 70→impl From<serde_json::Error> for ClientError {
 71→    fn from(e: serde_json::Error) -> Self {
 72→        Self::Json(e)
 73→    }
 74→}
 75→
 76→#[cfg(feature = "client")]
 77→impl From<reqwest::Error> for ClientError {
 78→    fn from(e: reqwest::Error) -> Self {
 79→        Self::Http(e)
 80→    }
 81→}
 82→
 83→/// System adapter client for JSON-RPC communication
 84→pub enum Client {
 85→    /// Stdio transport - communicate via stdin/stdout with a child process
 86→    Stdio {
 87→        _child: Box<Child>,
 88→        stdin: ChildStdin,
 89→        stdout: BufReader<ChildStdout>,
 90→    },
 91→    /// HTTP transport - communicate via HTTP POST requests
 92→    #[cfg(feature = "client")]
 93→    Http {
 94→        client: reqwest::Client,
 95→        endpoint: String,
 96→    },
 97→}
 98→
 99→impl Client {
100→    /// Create a client using stdio transport by spawning a command
101→    pub fn stdio(
102→        command: impl AsRef<str>,
103→        args: Vec<String>,
104→        env: HashMap<String, String>,
105→    ) -> Result<Self> {
106→        let command_str = command.as_ref();
107→        let mut cmd = Command::new(command_str);
108→
109→        cmd.args(args);
110→        for (key, value) in env {
111→            cmd.env(key, value);
112→        }
113→
114→        cmd.stdin(std::process::Stdio::piped())
115→            .stdout(std::process::Stdio::piped())
116→            .stderr(std::process::Stdio::inherit());
117→
118→        let mut child = cmd.spawn().map_err(|e| {
119→            ClientError::Transport(format!(
120→                "Failed to start stdio command '{command_str}': {e}"
121→            ))
122→        })?;
123→
124→        let stdin = child
125→            .stdin
126→            .take()
127→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdin".to_string()))?;
128→        let stdout = child
129→            .stdout
130→            .take()
131→            .ok_or_else(|| ClientError::Transport("Stdio child missing stdout".to_string()))?;
132→
133→        Ok(Self::Stdio {
134→            _child: Box::new(child),
135→            stdin,
136→            stdout: BufReader::new(stdout),
137→        })
138→    }
139→
140→    /// Create a client using HTTP transport
141→    #[cfg(feature = "client")]
142→    pub fn http(endpoint: impl Into<String>) -> Self {
143→        Self::Http {
144→            client: reqwest::Client::new(),
145→            endpoint: endpoint.into(),
146→        }
147→    }
148→
149→    /// Get the transport name
150→    pub fn transport_name(&self) -> &'static str {
151→        match self {
152→            Self::Stdio { .. } => "stdio",
153→            #[cfg(feature = "client")]
154→            Self::Http { .. } => "http",
155→        }
156→    }
157→
158→    /// Query available RPC methods from the server
159→    pub async fn rpc_methods(&mut self) -> Result<Vec<String>> {
160→        let request = JsonRpcRequest::new(1, methods::RPC_METHODS, serde_json::json!({}));
161→        let response: JsonRpcResponse<serde_json::Value> = self.call_typed(request).await?;
162→
163→        let methods = response
164→            .result
165→            .as_ref()
166→            .and_then(|v| v.get("methods"))
167→            .and_then(|v| v.as_array())
168→            .ok_or_else(|| {
169→                ClientError::InvalidResponse("Response missing result.methods array".to_string())
170→            })?
171→            .iter()
172→            .filter_map(|v| v.as_str().map(ToString::to_string))
173→            .collect();
174→
175→        Ok(methods)
176→    }
177→
178→    /// Setup a benchmark run with ETL configuration
179→    pub async fn setup(
180→        &mut self,
181→        run_id: uuid::Uuid,
182→        datasets: std::collections::HashMap<String, crate::DatasetConfig>,
183→    ) -> Result<crate::SetupResponse> {
184→        let request = crate::SetupRequest { run_id, datasets };
185→        let rpc_request = JsonRpcRequest::new(1, crate::methods::SETUP, request);
186→        let response = self.call_typed(rpc_request).await?;
187→        response
188→            .result
189→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
190→    }
191→
192→    /// Get query method/driver information for a benchmark run
193→    pub async fn query_method(&mut self, run_id: uuid::Uuid) -> Result<crate::QueryMethodResponse> {
194→        let request = crate::QueryMethodRequest { run_id };
195→        let rpc_request = JsonRpcRequest::new(1, crate::methods::QUERY_METHOD, request);
196→        let response = self.call_typed(rpc_request).await?;
197→        response
198→            .result
199→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
200→    }
201→
202→    /// Teardown a benchmark run
203→    pub async fn teardown(&mut self, run_id: uuid::Uuid) -> Result<crate::TeardownResponse> {
204→        let request = crate::TeardownRequest { run_id };
205→        let rpc_request = JsonRpcRequest::new(1, crate::methods::TEARDOWN, request);
206→        let response = self.call_typed(rpc_request).await?;
207→        response
208→            .result
209→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
210→    }
211→
212→    /// Collect current metrics from the system under test
213→    pub async fn metrics(&mut self, run_id: uuid::Uuid) -> Result<crate::MetricsResponse> {
214→        let request = crate::MetricsRequest { run_id };
215→        let rpc_request = JsonRpcRequest::new(1, crate::methods::METRICS, request);
216→        let response = self.call_typed(rpc_request).await?;
217→        response
218→            .result
219→            .ok_or_else(|| ClientError::InvalidResponse("Missing result".to_string()))
220→    }
221→
222→    /// Make a typed JSON-RPC call with request and response types
223→    async fn call_typed<Req: Serialize, Resp: DeserializeOwned>(
224→        &mut self,
225→        request: JsonRpcRequest<Req>,
226→    ) -> Result<JsonRpcResponse<Resp>> {
227→        let request_value = serde_json::to_value(request)?;
228→        let response_value = self.call_raw(request_value).await?;
229→        let response: JsonRpcResponse<Resp> = serde_json::from_value(response_value)?;
230→
231→        if let Some(error) = response.error {
232→            return Err(ClientError::JsonRpc(error));
233→        }
234→
235→        Ok(response)
236→    }
237→
238→    /// Make a raw JSON-RPC call with serde_json::Value
239→    async fn call_raw(&mut self, request: serde_json::Value) -> Result<serde_json::Value> {
240→        match self {
241→            Self::Stdio {
242→                _child: _,
243→                stdin,
244→                stdout,
245→            } => {
246→                let payload = serde_json::to_string(&request)?;
247→                stdin.write_all(payload.as_bytes()).await?;
248→                stdin.write_all(b"\n").await?;
249→                stdin.flush().await?;
250→
251→                let mut line = String::new();
252→                let read = stdout.read_line(&mut line).await?;
253→                if read == 0 {
254→                    return Err(ClientError::Transport(
255→                        "Stdio process closed stdout before responding".to_string(),
256→                    ));
257→                }
258→
259→                let response: serde_json::Value = serde_json::from_str(line.trim_end())?;
260→                if let Some(error) = response.get("error") {
261→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
262→                    return Err(ClientError::JsonRpc(error));
263→                }
264→                Ok(response)
265→            }
266→            #[cfg(feature = "client")]
267→            Self::Http { client, endpoint } => {
268→                let response = client
269→                    .post(endpoint.as_str())
270→                    .json(&request)
271→                    .send()
272→                    .await
273→                    .map_err(|e| {
274→                        ClientError::Transport(format!("Failed to POST to {endpoint}: {e}"))
275→                    })?;
276→
277→                let status = response.status();
278→                let value: serde_json::Value = response.json().await.map_err(|e| {
279→                    ClientError::Transport(format!(
280→                        "Failed to parse response body (status {status}): {e}"
281→                    ))
282→                })?;
283→
284→                if let Some(error) = value.get("error") {
285→                    let error: JsonRpcError = serde_json::from_value(error.clone())?;
286→                    return Err(ClientError::JsonRpc(error));
287→                }
288→                Ok(value)
289→            }
290→        }
291→    }
292→}
293→
294→/// Builder for creating a `Client` with various configuration options
295→pub struct ClientBuilder {
296→    transport: TransportConfig,
297→}
298→
299→enum TransportConfig {
300→    Stdio {
301→        command: String,
302→        args: Vec<String>,
303→        env: HashMap<String, String>,
304→    },
305→    #[cfg(feature = "client")]
306→    Http { endpoint: String },
307→}
308→
309→impl ClientBuilder {
310→    /// Create a builder for stdio transport
311→    pub fn stdio(command: impl Into<String>) -> Self {
312→        Self {
313→            transport: TransportConfig::Stdio {
314→                command: command.into(),
315→                args: Vec::new(),
316→                env: HashMap::new(),
317→            },
318→        }
319→    }
320→
321→    /// Create a builder for HTTP transport
322→    #[cfg(feature = "client")]
323→    pub fn http(endpoint: impl Into<String>) -> Self {
324→        Self {
325→            transport: TransportConfig::Http {
326→                endpoint: endpoint.into(),
327→            },
328→        }
329→    }
330→
331→    /// Add command-line arguments (stdio only)
332→    pub fn with_args(mut self, args: Vec<String>) -> Self {
333→        if let TransportConfig::Stdio {
334→            args: ref mut a, ..
335→        } = self.transport
336→        {
337→            *a = args;
338→        }
339→        self
340→    }
341→
342→    /// Add environment variables (stdio only)
343→    pub fn with_env(mut self, env: HashMap<String, String>) -> Self {
344→        if let TransportConfig::Stdio { env: ref mut e, .. } = self.transport {
345→            *e = env;
346→        }
347→        self
348→    }
349→
350→    /// Build the client
351→    pub fn build(self) -> Result<Client> {
352→        match self.transport {
353→            TransportConfig::Stdio { command, args, env } => Client::stdio(command, args, env),
354→            #[cfg(feature = "client")]
355→            TransportConfig::Http { endpoint } => Ok(Client::http(endpoint)),
356→        }
357→    }
358→}
