 68→/// Handler trait for implementing system adapter logic
 69→///
 70→/// Implement this trait to define how your system adapter handles
 71→/// setup, query_method, and teardown requests.
 72→#[async_trait]
 73→pub trait Handler: Send + Sync {
 74→    /// Setup a benchmark run with ETL configuration
 75→    async fn setup(
 76→        &mut self,
 77→        run_id: Uuid,
 78→        datasets: HashMap<String, DatasetConfig>,
 79→    ) -> std::result::Result<SetupResponse, String>;
 80→
 81→    /// Get query method/driver information for a benchmark run
 82→    async fn query_method(
 83→        &mut self,
 84→        run_id: Uuid,
 85→    ) -> std::result::Result<QueryMethodResponse, String>;
 86→
 87→    /// Teardown a benchmark run
 88→    async fn teardown(
 89→        &mut self,
 90→        run_id: Uuid,
 91→    ) -> std::result::Result<TeardownResponse, String>;
 92→
 93→    /// Collect current metrics from the system under test
 94→    ///
 95→    /// Called periodically by spicebench when `--scrape-sut-metrics` is enabled.
 96→    /// Returns a snapshot of resource utilization and ingestion progress.
 97→    /// Default implementation returns empty metrics.
 98→    async fn metrics(
 99→        &mut self,
100→        run_id: Uuid,
101→    ) -> std::result::Result<MetricsResponse, String> {
102→        let _ = run_id;
103→        Ok(MetricsResponse::default())
104→    }
105→
106→    /// List available RPC methods
107→    ///
108→    /// Override this if you want to add custom methods beyond the standard ones.
109→    fn rpc_methods(&self) -> Vec<String> {
110→        vec![
111→            methods::SETUP.to_string(),
112→            methods::QUERY_METHOD.to_string(),
113→            methods::TEARDOWN.to_string(),
114→            methods::METRICS.to_string(),
115→            methods::RPC_METHODS.to_string(),
116→        ]
