119→
120→/// System adapter server
121→pub struct Server<H: Handler> {
122→    handler: H,
123→}
124→
125→impl<H: Handler> Server<H> {
126→    /// Create a new server with the given handler
127→    pub fn new(handler: H) -> Self {
128→        Self { handler }
129→    }
130→
131→    /// Run the server on stdio (reads from stdin, writes to stdout)
132→    pub async fn run_stdio(&mut self) -> Result<()> {
133→        let stdin = tokio::io::stdin();
134→        let mut stdout = tokio::io::stdout();
135→        let mut reader = BufReader::new(stdin);
136→        let mut line = String::new();
137→
138→        loop {
139→            line.clear();
140→            let bytes_read = reader.read_line(&mut line).await?;
141→
142→            if bytes_read == 0 {
143→                // EOF reached
144→                break;
145→            }
146→
147→            let response = self.handle_request(line.trim()).await;
148→            let response_json = serde_json::to_string(&response)?;
149→            stdout.write_all(response_json.as_bytes()).await?;
150→            stdout.write_all(b"\n").await?;
151→            stdout.flush().await?;
152→        }
153→
154→        Ok(())
155→    }
156→
157→    /// Handle a single JSON-RPC request
158→    async fn handle_request(&mut self, request_str: &str) -> serde_json::Value {
159→        // Parse the request
160→        let request: serde_json::Value = match serde_json::from_str(request_str) {
161→            Ok(req) => req,
162→            Err(e) => {
163→                return serde_json::to_value(JsonRpcResponse::<()>::error(
164→                    serde_json::Value::Null,
165→                    JsonRpcError::new(error_codes::PARSE_ERROR, format!("Parse error: {e}")),
166→                ))
167→                .unwrap_or(serde_json::json!({}));
168→            }
169→        };
170→
171→        let id = request.get("id").cloned().unwrap_or(serde_json::Value::Null);
172→        let method = match request.get("method").and_then(|v| v.as_str()) {
173→            Some(m) => m,
174→            None => {
175→                return serde_json::to_value(JsonRpcResponse::<()>::error(
176→                    id,
177→                    JsonRpcError::new(error_codes::INVALID_REQUEST, "Missing method"),
178→                ))
179→                .unwrap_or(serde_json::json!({}));
180→            }
181→        };
182→
183→        // Dispatch to appropriate handler
184→        let result = match method {
185→            methods::SETUP => self.handle_setup(&request, id.clone()).await,
186→            methods::QUERY_METHOD => self.handle_query_method(&request, id.clone()).await,
187→            methods::TEARDOWN => self.handle_teardown(&request, id.clone()).await,
188→            methods::METRICS => self.handle_metrics(&request, id.clone()).await,
189→            methods::RPC_METHODS => self.handle_rpc_methods(id.clone()).await,
190→            _ => serde_json::to_value(JsonRpcResponse::<()>::error(
191→                id,
192→                JsonRpcError::new(error_codes::METHOD_NOT_FOUND, "Method not found"),
193→            ))
194→            .unwrap_or(serde_json::json!({})),
195→        };
196→
197→        result
198→    }
199→
200→    /// Parse and deserialize the `params` field from a JSON-RPC request.
201→    fn parse_params<T: DeserializeOwned>(
202→        request: &serde_json::Value,
203→        id: &serde_json::Value,
204→    ) -> std::result::Result<T, serde_json::Value> {
205→        let params = request.get("params").ok_or_else(|| {
206→            serde_json::to_value(JsonRpcResponse::<()>::error(
207→                id.clone(),
208→                JsonRpcError::new(error_codes::INVALID_PARAMS, "Missing params"),
209→            ))
210→            .unwrap_or(serde_json::json!({}))
211→        })?;
212→
213→        serde_json::from_value(params.clone()).map_err(|e| {
214→            serde_json::to_value(JsonRpcResponse::<()>::error(
215→                id.clone(),
216→                JsonRpcError::new(error_codes::INVALID_PARAMS, format!("Invalid params: {e}")),
217→            ))
218→            .unwrap_or(serde_json::json!({}))
219→        })
220→    }
221→
222→    /// Convert a handler result into a JSON-RPC response value.
223→    fn handler_response<T: serde::Serialize>(
224→        result: std::result::Result<T, String>,
225→        id: serde_json::Value,
226→    ) -> serde_json::Value {
227→        match result {
228→            Ok(response) => serde_json::to_value(JsonRpcResponse::success(id, response))
229→                .unwrap_or(serde_json::json!({})),
230→            Err(e) => serde_json::to_value(JsonRpcResponse::<()>::error(
231→                id,
232→                JsonRpcError::new(error_codes::INTERNAL_ERROR, e),
233→            ))
234→            .unwrap_or(serde_json::json!({})),
235→        }
236→    }
237→
238→    async fn handle_setup(&mut self, request: &serde_json::Value, id: serde_json::Value) -> serde_json::Value {
239→        let req: SetupRequest = match Self::parse_params(request, &id) {
240→            Ok(r) => r,
241→            Err(e) => return e,
242→        };
243→        Self::handler_response(self.handler.setup(req.run_id, req.datasets).await, id)
244→    }
245→
246→    async fn handle_query_method(&mut self, request: &serde_json::Value, id: serde_json::Value) -> serde_json::Value {
247→        let req: QueryMethodRequest = match Self::parse_params(request, &id) {
248→            Ok(r) => r,
249→            Err(e) => return e,
250→        };
251→        Self::handler_response(self.handler.query_method(req.run_id).await, id)
252→    }
253→
254→    async fn handle_teardown(&mut self, request: &serde_json::Value, id: serde_json::Value) -> serde_json::Value {
255→        let req: TeardownRequest = match Self::parse_params(request, &id) {
256→            Ok(r) => r,
257→            Err(e) => return e,
258→        };
259→        Self::handler_response(self.handler.teardown(req.run_id).await, id)
260→    }
261→
262→    async fn handle_metrics(&mut self, request: &serde_json::Value, id: serde_json::Value) -> serde_json::Value {
263→        let req: MetricsRequest = match Self::parse_params(request, &id) {
264→            Ok(r) => r,
265→            Err(e) => return e,
266→        };
267→        Self::handler_response(self.handler.metrics(req.run_id).await, id)
268→    }
269→
270→    async fn handle_rpc_methods(&mut self, id: serde_json::Value) -> serde_json::Value {
271→        let methods = self.handler.rpc_methods();
272→        let result = serde_json::json!({ "methods": methods });
273→        serde_json::to_value(JsonRpcResponse::success(id, result))
274→            .unwrap_or(serde_json::json!({}))
275→    }
276→}
