 17→//! JSON-RPC protocol definitions for system adapter communication.
 18→//!
 19→//! This crate defines the request/response types for the system adapter
 20→//! JSON-RPC protocol, which allows spicebench to communicate with external
 21→//! benchmark execution environments.
 22→//!
 23→//! # Features
 24→//!
 25→//! - **Protocol types**: Request/response types for setup, query_method, and teardown
 26→//! - **Client**: Ready-to-use client with Stdio and HTTP transports (requires `client` feature)
 27→//! - **Server**: Easy server implementation via Handler trait (requires `server` feature)
 28→//! - **JSON-RPC**: Standard JSON-RPC 2.0 envelope types
 29→//!
 30→//! # Client Example
 31→//!
 32→//! ```no_run
 33→//! # #[cfg(feature = "client")]
 34→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 35→//! use system_adapter_protocol::Client;
 36→//! use std::collections::HashMap;
 37→//! use uuid::Uuid;
 38→//!
 39→//! // Create an HTTP client
 40→//! let mut client = Client::http("http://localhost:8080");
 41→//!
 42→//! // Setup a benchmark run
 43→//! let run_id = Uuid::new_v4();
 44→//! let setup_response = client.setup(run_id, HashMap::new()).await?;
 45→//!
 46→//! // Get query method information
 47→//! let query_response = client.query_method(run_id).await?;
 48→//! println!("Driver: {:?}", query_response.driver);
 49→//!
 50→//! // Teardown the run
 51→//! let teardown_response = client.teardown(run_id).await?;
 52→//! # Ok(())
 53→//! # }
 54→//! ```
 55→//!
 56→//! # Server Example
 57→//!
 58→//! ```no_run
 59→//! # #[cfg(feature = "server")]
 60→//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
 61→//! use system_adapter_protocol::{
 62→//!     Handler, Server, SetupResponse, QueryMethodResponse, TeardownResponse,
 63→//!     AdbcDriver, DatasetConfig
 64→//! };
 65→//! use async_trait::async_trait;
 66→//! use std::collections::HashMap;
 67→//! use uuid::Uuid;
 68→//!
 69→//! struct MyHandler;
 70→//!
 71→//! #[async_trait]
 72→//! impl Handler for MyHandler {
 73→//!     async fn setup(
 74→//!         &mut self,
 75→//!         run_id: Uuid,
 76→//!         datasets: HashMap<String, DatasetConfig>,
 77→//!     ) -> Result<SetupResponse, String> {
 78→//!         // Your setup logic here
 79→//!         Ok(SetupResponse { ok: true })
 80→//!     }
 81→//!
 82→//!     async fn query_method(&mut self, run_id: Uuid) -> Result<QueryMethodResponse, String> {
 83→//!         Ok(QueryMethodResponse {
 84→//!             driver: AdbcDriver::Flightsql,
 85→//!             db_kwargs: HashMap::new(),
 86→//!         })
 87→//!     }
 88→//!
 89→//!     async fn teardown(&mut self, run_id: Uuid) -> Result<TeardownResponse, String> {
 90→//!         Ok(TeardownResponse { ok: true })
 91→//!     }
 92→//! }
 93→//!
 94→//! // Run the server on stdio
 95→//! let mut server = Server::new(MyHandler);
 96→//! server.run_stdio().await?;
 97→//! # Ok(())
 98→//! # }
 99→//! ```
