 93→    /// Collect current metrics from the system under test
 94→    ///
 95→    /// Called periodically by spicebench when `--scrape-sut-metrics` is enabled.
 96→    /// Returns a snapshot of resource utilization and ingestion progress.
 97→    /// Default implementation returns empty metrics.
 98→    async fn metrics(
 99→        &mut self,
100→        run_id: Uuid,
101→    ) -> std::result::Result<MetricsResponse, String> {
102→        let _ = run_id;
103→        Ok(MetricsResponse::default())
104→    }
